declare module '*.html' {
  const source: string
  export default source
}

declare module '*.css' {
  const source: string
  export default source
}

declare module '*.js' {
  const source: string
  export default source
}

declare module '*.md' {
  const source: string
  export default source
}

declare module '*?raw' {
  const source: string
  export default source
}
